import{_ as t,l as o,o as a,c as s,v as e,p as l,x as i,d as n,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const v=JSON.parse('{"title":"Firecracker","description":"","frontmatter":{"title":"Firecracker","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/firecracker-microvm.md","filePath":"cs/firecracker-microvm.md","lastUpdated":1789023840000}'),h={name:"cs/firecracker-microvm.md"};function m(M,r,V,k,f,u){const c=o("Mermaid");return a(),s("div",null,[r[1]||(r[1]=e('<h1 id="firecracker" tabindex="-1">Firecracker <a class="header-anchor" href="#firecracker" aria-label="Permalink to &quot;Firecracker&quot;">​</a></h1><div class="epigraph"><p>Firecracker 是用 Rust 写的瘦 VMM：KVM + 极少 virtio 设备，为每函数或每容器起一台微 VM，启动以毫秒计。</p><footer>—— 据 Firecracker 设计文档；[KVM/QEMU](/cs/kvm-qemu) 为完整 VMM 对照</footer></div><p><a href="/cs/gvisor">gVisor</a> 截 syscall。<a href="/cs/kvm-qemu">QEMU</a> 设备太多。缺口是 <strong>microVM</strong>：Firecracker 砍设备模型。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>只留 virtio-net/blk、串口、非常少的 PCI。缺口：与 <a href="/cs/container-runtime">容器</a> 的 jailer（chroot、cgroup、seccomp 锁 VMM）；快照恢复。本课不把 Lambda 产品写成云广告。</p><p><span class="marginnote">无 USB、无 VGA。对象是攻击面与冷启动，不是桌面虚拟化。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>jailer 起进程 → KVM 建 VM → 客内核 + 极简 rootfs。对照 QEMU：少 exit 路径种类。对照 runc：多一层客户内核。对照 <a href="/cs/sriov-passthrough">SR-IOV</a>：微 VM 常用 virtio 而非直通。</p>',8)),(a(),l(p,null,{default:i(()=>[d(c,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20JAIL%5B%22jailer%20%E9%94%81%20VMM%22%5D%20--%3E%20FC%5B%22Firecracker%22%5D%0A%20%20FC%20--%3E%20KVM%5B%22KVM%20vCPU%22%5D%0A%20%20KVM%20--%3E%20GUEST%5B%22%E6%9E%81%E7%AE%80%E5%AE%A2%E6%88%B7%E6%9C%BA%22%5D%0A"})]),fallback:i(()=>[...r[0]||(r[0]=[n(" Loading... ",-1)])]),_:1})),r[2]||(r[2]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Firecracker 把「每租户一内核」的隔离做到能水平铺开，用砍设备换启动与 CVE 面。客户仍是真内核，syscall 兼容好于 gVisor。不要写成 serverless 计费。与 <a href="/cs/live-migration">热迁移</a>：有快照，完整 live 不是主路径。</p><p>内核配置要为微 VM 裁剪——<a href="/cs/kernel-config-build">kbuild</a>。</p><p>实现上：API 套接字在 jailer 之后才听，攻击面从 VMM 进程开始锁。无 PCI 扫描减少客户攻击。快照把内存+设备状态当微函数冷启动加速。 读法上只引用<a href="/cs/gvisor">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「虚拟化与隔离进阶 / 容器与内核形态」课序里，对象是 <strong>Firecracker</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有 API 套接字。不保证嵌套。下一课 Kata：容器接口 + VM。</p><p>版本字段会变，课序钉的是机制对象「Firecracker」，不是某一主线内核的结构体名。 后课默认：微 VMM 用 KVM 跑裁剪客户。Kata 把 OCI 接到 VM，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Firecracker：瘦设备模型的 KVM VMM。</li><li>jailer 锁住 VMM 进程本身。</li><li>Kata 是下一课。</li><li>出处：Firecracker 文档；KVM；OCI。</li></ul>',11))])}const E=t(h,[["render",m]]);export{v as __pageData,E as default};
